def list_collections(database, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0273000" if __import__("os").path.isdir("./environment_mix/0273000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    ops = _load("mongo_operations.json")
    conns = _load("mongo_connections.json")
    dbs = _load("mongo_databases.json")
    cols = _load("mongo_collections.json")

    def _new_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{hashlib.sha256(os.urandom(16)).hexdigest()[:10]}"

    op_id = _new_id("op")
    op = {
        "id": op_id,
        "connection_id": None,
        "tool_name": "list-collections",
        "database": database,
        "collection": None,
        "arguments": {"database": database},
        "status": "received",
        "started_at": None,
        "ended_at": None,
        "duration_ms": None,
        "result": None,
        "result_truncated": False,
        "error": None,
        "read_preference": None,
        "write_concern": None,
        "created_at": now,
        "updated_at": now,
    }
    ops.append(op)
    _save("mongo_operations.json", ops)

    def _finish(status, result=None, error=None, connection_id=None):
        ended = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        duration_ms = int(max(0, round((time.time() - t0) * 1000)))
        ops2 = _load("mongo_operations.json")
        for r in ops2:
            if r.get("id") == op_id:
                if r.get("status") == "received":
                    r["status"] = "running"
                    r["started_at"] = r.get("started_at") or now
                r["status"] = status
                r["ended_at"] = ended
                r["duration_ms"] = duration_ms
                r["updated_at"] = ended
                if connection_id is not None:
                    r["connection_id"] = connection_id
                r["result"] = result
                r["error"] = error
                r["result_truncated"] = bool(r.get("result_truncated", False))
                break
        _save("mongo_operations.json", ops2)
        if status == "failed":
            return {"id": op_id, "status": "failed", "error": error}
        return {"id": op_id, "status": "succeeded", "result": result}

    # Validate
    if not isinstance(database, str):
        err = _err("VALIDATION_ERROR", "database must be a string")
        return _finish("failed", error=err["error"])
    database = database.strip()
    if not database:
        err = _err("VALIDATION_ERROR", "database is required")
        return _finish("failed", error=err["error"])

    # Ambient auth: find a connected connection that can serve the call
    conn = None
    for c in conns:
        if c.get("status") == "connected":
            conn = c
            break
    if conn is None:
        err = _err("UNAUTHORIZED", "No active connected session")
        return _finish("failed", error=err["error"])

    conn_id = conn["id"]

    # Not found if database not known/visible in catalog (offline)
    db_row = None
    for d in dbs:
        if d.get("connection_id") == conn_id and d.get("name") == database and d.get("status") != "dropped":
            db_row = d
            break
    if db_row is None:
        err = _err("NOT_FOUND", "Database not found")
        return _finish("failed", error=err["error"], connection_id=conn_id)

    # Return active/non-dropped collections for that db
    out = []
    for c in cols:
        if c.get("connection_id") == conn_id and c.get("database_name") == database and c.get("status") != "dropped":
            out.append({
                "name": c.get("name"),
                "type": c.get("type"),
                "options": c.get("options"),
                "status": c.get("status"),
            })
    out.sort(key=lambda x: (x.get("name") or ""))

    result = {"database": database, "collections": out}
    return _finish("succeeded", result=result, connection_id=conn_id)

def collection_schema(database, collection, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0273000" if __import__("os").path.isdir("./environment_mix/0273000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    TOOL = "collection-schema"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_op_id():
        return f"op_{int(time.time()*1000)}_{hashlib.sha256(os.urandom(16)).hexdigest()[:16]}"

    def _validate_ns_name(v, field):
        if not isinstance(v, str) or not v.strip():
            return f"{field} must be a non-empty string"
        if len(v.strip()) > 64:
            return f"{field} length must be between 1 and 64"
        return None

    def _op_create(conn_id):
        ops = _load("mongo_operations.json")
        now = _now()
        op_id = _new_op_id()
        ops.append({
            "id": op_id,
            "connection_id": conn_id,
            "tool_name": TOOL,
            "database": database,
            "collection": collection,
            "arguments": {"database": database, "collection": collection},
            "status": "received",
            "started_at": None,
            "ended_at": None,
            "duration_ms": None,
            "result": None,
            "result_truncated": False,
            "error": None,
            "read_preference": None,
            "write_concern": None,
            "created_at": now,
            "updated_at": now,
        })
        _save("mongo_operations.json", ops)
        return op_id, now

    def _op_finalize(op_id, created_at, t0, status, conn_id=None, result=None, error=None, truncated=False):
        ops = _load("mongo_operations.json")
        ended = _now()
        duration_ms = int(max(0, round((time.time() - t0) * 1000)))
        for r in ops:
            if r.get("id") == op_id:
                if r.get("status") == "received":
                    r["status"] = "running"
                    r["started_at"] = r.get("started_at") or r.get("created_at") or created_at or ended
                    r["updated_at"] = ended
                r["status"] = status
                r["ended_at"] = ended
                r["duration_ms"] = duration_ms
                r["updated_at"] = ended
                if conn_id is not None:
                    r["connection_id"] = conn_id
                r["result"] = result
                r["error"] = error
                r["result_truncated"] = bool(truncated)
                _save("mongo_operations.json", ops)
                return True
        return False

    msg = _validate_ns_name(database, "database") or _validate_ns_name(collection, "collection")

    conns = _load("mongo_connections.json")
    dbs = _load("mongo_databases.json")
    cols = _load("mongo_collections.json")

    connected = [c for c in conns if c.get("status") == "connected" and isinstance(c.get("id"), str)]
    chosen = None
    chosen_db = None
    chosen_col = None
    for c in connected:
        db = next((d for d in dbs if d.get("connection_id") == c.get("id") and d.get("name") == database and d.get("status") != "dropped"), None)
        col = None
        if db:
            col = next((cc for cc in cols if cc.get("connection_id") == c.get("id") and (cc.get("database_id") == db.get("id") or cc.get("database_name") == database) and cc.get("name") == collection and cc.get("status") != "dropped"), None)
        if db and col:
            chosen, chosen_db, chosen_col = c, db, col
            break
    if not chosen and connected:
        chosen = connected[0]

    op_id, created_at = _op_create(chosen.get("id") if chosen else None)
    t0 = time.time()

    if msg:
        _op_finalize(op_id, created_at, t0, "failed", conn_id=chosen.get("id") if chosen else None, error={"code": "VALIDATION_ERROR", "message": msg})
        return _err("VALIDATION_ERROR", msg, operation_id=op_id)

    if not chosen:
        _op_finalize(op_id, created_at, t0, "failed", conn_id=None, error={"code": "UNAUTHORIZED", "message": "No connected session available for this operation."})
        return _err("UNAUTHORIZED", "No connected session available for this operation.", operation_id=op_id)

    if not chosen_db or not chosen_col:
        _op_finalize(op_id, created_at, t0, "failed", conn_id=chosen.get("id"), error={"code": "NOT_FOUND", "message": "Database or collection not found in catalog."})
        return _err("NOT_FOUND", "Database or collection not found in catalog.", operation_id=op_id)

    # "Infer" schema based on cached metadata only (offline): use existing schema_inference if present, else synthesize minimal.
    now = _now()
    schema = chosen_col.get("schema_inference")
    if not isinstance(schema, dict):
        schema = {
            "collection": collection,
            "database": database,
            "inference": {
                "method": "catalog-only",
                "sample_size": 0,
                "fields": []
            }
        }

    # Cache into collection record
    cols2 = cols
    for cc in cols2:
        if cc.get("id") == chosen_col.get("id"):
            cc["schema_inference"] = schema
            cc["schema_refreshed_at"] = now
            cc["updated_at"] = now
            break
    _save("mongo_collections.json", cols2)

    result = {"schema": schema}
    _op_finalize(op_id, created_at, t0, "succeeded", conn_id=chosen.get("id"), result=result, truncated=False)
    return {"operation_id": op_id, "database": database, "collection": collection, "schema": schema}

def find(database, collection, filter=None, projection=None, limit=None, sort=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0273000" if __import__("os").path.isdir("./environment_mix/0273000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _op_id():
        return "op_" + uuid.uuid4().hex

    def _create_operation_record(connection_id, status, started_at=None, ended_at=None, duration_ms=None, result=None, result_truncated=False, error=None):
        ops = _load("mongo_operations.json")
        now = _now()
        args = {"database": database, "collection": collection}
        if filter is not None:
            args["filter"] = filter
        if projection is not None:
            args["projection"] = projection
        if sort is not None:
            args["sort"] = sort
        if limit is not None:
            args["limit"] = limit
        op = {
            "id": _op_id(),
            "connection_id": connection_id,
            "tool_name": "find",
            "database": database,
            "collection": collection,
            "arguments": args,
            "status": status,
            "started_at": started_at,
            "ended_at": ended_at,
            "duration_ms": duration_ms,
            "result": result,
            "result_truncated": bool(result_truncated),
            "error": error,
            "read_preference": None,
            "write_concern": None,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op)
        _save("mongo_operations.json", ops)
        return op

    def _json_bytes(x):
        try:
            return len(json.dumps(x, ensure_ascii=False, separators=(",", ":"), sort_keys=True).encode("utf-8"))
        except TypeError:
            return len(json.dumps(str(x), ensure_ascii=False, separators=(",", ":"), sort_keys=True).encode("utf-8"))

    t0 = time.time()

    # Validate
    if not isinstance(database, str) or not database.strip():
        op = _create_operation_record(None, "failed", started_at=_now(), ended_at=_now(), duration_ms=0, error={"code": "VALIDATION_ERROR", "message": "database is required and must be a non-empty string"})
        return _err("VALIDATION_ERROR", "database is required and must be a non-empty string", operation_id=op["id"])
    if not isinstance(collection, str) or not collection.strip():
        op = _create_operation_record(None, "failed", started_at=_now(), ended_at=_now(), duration_ms=0, error={"code": "VALIDATION_ERROR", "message": "collection is required and must be a non-empty string"})
        return _err("VALIDATION_ERROR", "collection is required and must be a non-empty string", operation_id=op["id"])
    if filter is not None and not isinstance(filter, dict):
        op = _create_operation_record(None, "failed", started_at=_now(), ended_at=_now(), duration_ms=0, error={"code": "VALIDATION_ERROR", "message": "filter must be an object when provided"})
        return _err("VALIDATION_ERROR", "filter must be an object when provided", operation_id=op["id"])
    if projection is not None and not isinstance(projection, dict):
        op = _create_operation_record(None, "failed", started_at=_now(), ended_at=_now(), duration_ms=0, error={"code": "VALIDATION_ERROR", "message": "projection must be an object when provided"})
        return _err("VALIDATION_ERROR", "projection must be an object when provided", operation_id=op["id"])
    if sort is not None and not isinstance(sort, dict):
        op = _create_operation_record(None, "failed", started_at=_now(), ended_at=_now(), duration_ms=0, error={"code": "VALIDATION_ERROR", "message": "sort must be an object when provided"})
        return _err("VALIDATION_ERROR", "sort must be an object when provided", operation_id=op["id"])
    if limit is None:
        limit = 10
    if not isinstance(limit, (int, float)) or isinstance(limit, bool):
        op = _create_operation_record(None, "failed", started_at=_now(), ended_at=_now(), duration_ms=0, error={"code": "VALIDATION_ERROR", "message": "limit must be a number"})
        return _err("VALIDATION_ERROR", "limit must be a number", operation_id=op["id"])
    limit_int = int(limit)
    if limit_int < 0 or limit_int > 1000:
        op = _create_operation_record(None, "failed", started_at=_now(), ended_at=_now(), duration_ms=0, error={"code": "VALIDATION_ERROR", "message": "limit must be between 0 and 1000"})
        return _err("VALIDATION_ERROR", "limit must be between 0 and 1000", operation_id=op["id"])

    # Authorization: need connected + known collection in catalog
    conns = _load("mongo_connections.json")
    dbs = _load("mongo_databases.json")
    cols = _load("mongo_collections.json")
    connected_ids = {c["id"] for c in conns if isinstance(c, dict) and c.get("status") == "connected"}

    col_row = None
    for c in cols:
        if not isinstance(c, dict):
            continue
        if c.get("connection_id") in connected_ids and c.get("database_name") == database and c.get("name") == collection and c.get("status") != "dropped":
            db_row = next((d for d in dbs if isinstance(d, dict) and d.get("id") == c.get("database_id")), None)
            if db_row and db_row.get("connection_id") == c.get("connection_id") and db_row.get("name") == database and db_row.get("status") != "dropped":
                col_row = c
                break

    op = _create_operation_record(col_row["connection_id"] if col_row else None, "received")
    ops = _load("mongo_operations.json")
    for r in ops:
        if r.get("id") == op["id"]:
            r["status"] = "running"
            r["started_at"] = _now()
            r["updated_at"] = _now()
            op = r
            break
    _save("mongo_operations.json", ops)

    if not col_row:
        ended = _now()
        duration_ms = max(0, int((time.time() - t0) * 1000))
        ops = _load("mongo_operations.json")
        for r in ops:
            if r.get("id") == op["id"]:
                r["status"] = "failed"
                r["ended_at"] = ended
                r["duration_ms"] = duration_ms
                r["error"] = {"code": "UNAUTHORIZED", "message": "No connected session available for this operation, or database/collection not found in catalog."}
                r["updated_at"] = ended
                op = r
                break
        _save("mongo_operations.json", ops)
        return _err("UNAUTHORIZED", "No connected session available for this operation, or database/collection not found in catalog.", operation_id=op["id"])

    # Offline backend: cannot actually query; return empty docs but still succeed and log
    # Apply safety: if limit==0 return empty; else empty.
    docs = []
    result_obj = {"documents": docs, "returned": 0, "limit": limit_int, "note": "Offline mode: no MongoDB query executed."}

    truncated = False
    MAX_BYTES = 128 * 1024
    if _json_bytes(result_obj) > MAX_BYTES:
        truncated = True
        result_obj = {"documents": [], "returned": 0, "limit": limit_int, "note": "Offline mode: result truncated."}

    ended = _now()
    duration_ms = max(0, int((time.time() - t0) * 1000))
    ops = _load("mongo_operations.json")
    for r in ops:
        if r.get("id") == op["id"]:
            r["status"] = "succeeded"
            r["ended_at"] = ended
            r["duration_ms"] = duration_ms
            r["result"] = result_obj
            r["result_truncated"] = bool(truncated)
            r["error"] = None
            r["updated_at"] = ended
            op = r
            break
    _save("mongo_operations.json", ops)

    return {"operation_id": op["id"], "result": result_obj}

def insert_many(database, collection, documents, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0273000" if __import__("os").path.isdir("./environment_mix/0273000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _op_id():
        return "op_" + uuid.uuid4().hex

    def _create_operation_record(connection_id, status, started_at=None, ended_at=None, duration_ms=None, result=None, result_truncated=False, error=None):
        ops = _load("mongo_operations.json")
        now = _now()
        op = {
            "id": _op_id(),
            "connection_id": connection_id,
            "tool_name": "insert-many",
            "database": database,
            "collection": collection,
            "arguments": {"database": database, "collection": collection, "documents": documents},
            "status": status,
            "started_at": started_at,
            "ended_at": ended_at,
            "duration_ms": duration_ms,
            "result": result,
            "result_truncated": bool(result_truncated),
            "error": error,
            "read_preference": None,
            "write_concern": None,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op)
        _save("mongo_operations.json", ops)
        return op

    def _json_bytes(x):
        try:
            return len(json.dumps(x, ensure_ascii=False, separators=(",", ":"), sort_keys=True).encode("utf-8"))
        except TypeError:
            return len(json.dumps(str(x), ensure_ascii=False, separators=(",", ":"), sort_keys=True).encode("utf-8"))

    t0 = time.time()

    # Validate
    if not isinstance(database, str) or not database.strip():
        op = _create_operation_record(None, "failed", started_at=_now(), ended_at=_now(), duration_ms=0, error={"code": "VALIDATION_ERROR", "message": "database is required and must be a non-empty string"})
        return _err("VALIDATION_ERROR", "database is required and must be a non-empty string", operation_id=op["id"])
    if not isinstance(collection, str) or not collection.strip():
        op = _create_operation_record(None, "failed", started_at=_now(), ended_at=_now(), duration_ms=0, error={"code": "VALIDATION_ERROR", "message": "collection is required and must be a non-empty string"})
        return _err("VALIDATION_ERROR", "collection is required and must be a non-empty string", operation_id=op["id"])
    if not isinstance(documents, list) or len(documents) == 0:
        op = _create_operation_record(None, "failed", started_at=_now(), ended_at=_now(), duration_ms=0, error={"code": "VALIDATION_ERROR", "message": "documents must be a non-empty array"})
        return _err("VALIDATION_ERROR", "documents must be a non-empty array", operation_id=op["id"])
    for i, d in enumerate(documents):
        if not isinstance(d, dict):
            op = _create_operation_record(None, "failed", started_at=_now(), ended_at=_now(), duration_ms=0, error={"code": "VALIDATION_ERROR", "message": f"documents[{i}] must be an object"})
            return _err("VALIDATION_ERROR", f"documents[{i}] must be an object", operation_id=op["id"])

    MAX_DOCS = 1000
    if len(documents) > MAX_DOCS:
        op = _create_operation_record(None, "failed", started_at=_now(), ended_at=_now(), duration_ms=0, error={"code": "VALIDATION_ERROR", "message": f"documents exceeds maximum of {MAX_DOCS} per call"})
        return _err("VALIDATION_ERROR", f"documents exceeds maximum of {MAX_DOCS} per call", operation_id=op["id"])

    MAX_PAYLOAD_BYTES = 2 * 1024 * 1024
    if _json_bytes(documents) > MAX_PAYLOAD_BYTES:
        op = _create_operation_record(None, "failed", started_at=_now(), ended_at=_now(), duration_ms=0, error={"code": "VALIDATION_ERROR", "message": "documents payload too large"})
        return _err("VALIDATION_ERROR", "documents payload too large", operation_id=op["id"])

    # Authorization: connected + collection exists
    conns = _load("mongo_connections.json")
    dbs = _load("mongo_databases.json")
    cols = _load("mongo_collections.json")
    connected_ids = {c["id"] for c in conns if isinstance(c, dict) and c.get("status") == "connected"}

    col_row = None
    for c in cols:
        if not isinstance(c, dict):
            continue
        if c.get("connection_id") in connected_ids and c.get("database_name") == database and c.get("name") == collection and c.get("status") != "dropped":
            db_row = next((d for d in dbs if isinstance(d, dict) and d.get("id") == c.get("database_id")), None)
            if db_row and db_row.get("connection_id") == c.get("connection_id") and db_row.get("name") == database and db_row.get("status") != "dropped":
                col_row = c
                break

    op = _create_operation_record(col_row["connection_id"] if col_row else None, "received")
    ops = _load("mongo_operations.json")
    for r in ops:
        if r.get("id") == op["id"]:
            r["status"] = "running"
            r["started_at"] = _now()
            r["updated_at"] = _now()
            op = r
            break
    _save("mongo_operations.json", ops)

    if not col_row:
        ended = _now()
        duration_ms = max(0, int((time.time() - t0) * 1000))
        ops = _load("mongo_operations.json")
        for r in ops:
            if r.get("id") == op["id"]:
                r["status"] = "failed"
                r["ended_at"] = ended
                r["duration_ms"] = duration_ms
                r["error"] = {"code": "UNAUTHORIZED", "message": "No connected session available for this operation, or database/collection not found in catalog."}
                r["updated_at"] = ended
                op = r
                break
        _save("mongo_operations.json", ops)
        return _err("UNAUTHORIZED", "No connected session available for this operation, or database/collection not found in catalog.", operation_id=op["id"])

    # Offline: can't actually insert. Still must not claim success without effect.
    # Therefore: return failed, since no remote write can occur in this offline server.
    ended = _now()
    duration_ms = max(0, int((time.time() - t0) * 1000))
    ops = _load("mongo_operations.json")
