        })
        _save("mongo_operations.json", ops)
        return op_id

    def _op_finish(op_id, t0, status, conn_id=None, result=None, error=None, truncated=False):
        ended = _now()
        duration_ms = int(max(0, round((time.time() - t0) * 1000)))
        ops = _load("mongo_operations.json")
        for r in ops:
            if r.get("id") == op_id:
                if r.get("status") == "received":
                    r["status"] = "running"
                    r["started_at"] = r.get("started_at") or r.get("created_at") or ended
                r["status"] = status
                r["ended_at"] = ended
                r["duration_ms"] = duration_ms
                r["updated_at"] = ended
                if conn_id is not None:
                    r["connection_id"] = conn_id
                r["result"] = result
                r["error"] = error
                r["result_truncated"] = bool(truncated)
                _save("mongo_operations.json", ops)
                return True
        return False

    conns = _load("mongo_connections.json")
    any_conn_id = next((c.get("id") for c in conns if c.get("id")), None)
    op_id = _op_new(any_conn_id)
    t0 = time.time()

    msg = _validate_name(database, "database") or _validate_name(collection, "collection")
    if msg:
        _op_finish(op_id, t0, "failed", conn_id=any_conn_id, error={"code": "VALIDATION_ERROR", "message": msg})
        return _err("VALIDATION_ERROR", msg, operation_id=op_id)

    if not isinstance(method, list) or len(method) < 1:
        _op_finish(op_id, t0, "failed", conn_id=any_conn_id, error={"code": "VALIDATION_ERROR", "message": "method must be an array of one or more method objects"})
        return _err("VALIDATION_ERROR", "method must be an array of one or more method objects", operation_id=op_id)

    # Validate method objects minimally per schema
    allowed = {"aggregate", "find", "count"}
    for m in method:
        if not isinstance(m, dict):
            _op_finish(op_id, t0, "failed", conn_id=any_conn_id, error={"code": "VALIDATION_ERROR", "message": "Each method entry must be an object"})
            return _err("VALIDATION_ERROR", "Each method entry must be an object", operation_id=op_id)
        if m.get("name") not in allowed:
            _op_finish(op_id, t0, "failed", conn_id=any_conn_id, error={"code": "VALIDATION_ERROR", "message": "method.name must be one of {'aggregate','find','count'}"})
            return _err("VALIDATION_ERROR", "method.name must be one of {'aggregate','find','count'}", operation_id=op_id)
        if "arguments" not in m or not isinstance(m.get("arguments"), dict):
            _op_finish(op_id, t0, "failed", conn_id=any_conn_id, error={"code": "VALIDATION_ERROR", "message": "method.arguments must be an object"})
            return _err("VALIDATION_ERROR", "method.arguments must be an object", operation_id=op_id)
        if m["name"] == "aggregate":
            if not isinstance(m["arguments"].get("pipeline"), list) or len(m["arguments"]["pipeline"]) == 0:
                _op_finish(op_id, t0, "failed", conn_id=any_conn_id, error={"code": "VALIDATION_ERROR", "message": "aggregate.arguments.pipeline must be a non-empty array"})
                return _err("VALIDATION_ERROR", "aggregate.arguments.pipeline must be a non-empty array", operation_id=op_id)

    dbs = _load("mongo_databases.json")
    cols = _load("mongo_collections.json")
    ctx = None
    for c in conns:
        if c.get("status") != "connected":
            continue
        db_row = next((d for d in dbs if d.get("connection_id") == c.get("id") and d.get("name") == database and d.get("status") != "dropped"), None)
        col_row = None
        if db_row:
            col_row = next((cc for cc in cols if cc.get("connection_id") == c.get("id") and cc.get("database_id") == db_row.get("id") and cc.get("name") == collection and cc.get("status") != "dropped"), None)
        if not col_row:
            col_row = next((cc for cc in cols if cc.get("connection_id") == c.get("id") and cc.get("database_name") == database and cc.get("name") == collection and cc.get("status") != "dropped"), None)
            if col_row and not db_row:
                db_row = next((d for d in dbs if d.get("id") == col_row.get("database_id")), None)
        if db_row and col_row:
            ctx = (c, db_row, col_row)
            break

    if not ctx:
        has_connected = any(c.get("status") == "connected" for c in conns)
        code = "UNAUTHORIZED" if not has_connected else "NOT_FOUND"
        msg2 = "No connected session available for this operation." if code == "UNAUTHORIZED" else "Database or collection not found."
        _op_finish(op_id, t0, "failed", conn_id=any_conn_id, error={"code": code, "message": msg2})
        return _err(code, msg2, operation_id=op_id)

    conn, db_row, col_row = ctx

    # Offline deterministic "plan"
    seed = f"{conn.get('id')}|{database}|{collection}|{json.dumps(method, sort_keys=True, ensure_ascii=False)}"
    h = hashlib.sha256(seed.encode("utf-8")).hexdigest()
    plan = {
        "queryPlanner": {
            "namespace": f"{database}.{collection}",
            "winningPlan": {
                "stage": "COLLSCAN" if int(h[:2], 16) % 3 == 0 else "IXSCAN",
                "details": {"hash": h[:16]}
            }
        },
        "executionStats": {
            "nReturned": int(h[2:6], 16) % 1000,
            "totalKeysExamined": int(h[6:10], 16) % 5000,
            "totalDocsExamined": int(h[10:14], 16) % 5000,
            "executionTimeMillis": int(h[14:18], 16) % 200,
        },
        "ok": 1
    }

    result = {"explain": plan}
    _op_finish(op_id, t0, "succeeded", conn_id=conn.get("id"), result=result, error=None, truncated=False)
    return result

