    # Sort by updated_at desc, fallback to created_at, then id
    def _sort_key(r):
        ud = _parse_dt(r.get("updated_at")) or _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1)
        return (ud, r.get("id") or "")

    rows.sort(key=_sort_key, reverse=True)

    total = len(rows)
    start = (page - 1) * pageSize
    end = start + pageSize
    page_rows = rows[start:end]
    has_more = end < total

    out_rows = []
    for r in page_rows:
        item = {}
        for k in [
            "id",
            "client_fingerprint",
            "topology_type",
            "server_version",
            "auth_mechanism",
            "default_database",
            "last_connected_at",
            "last_error",
            "status",
            "created_at",
            "updated_at",
        ]:
            if k in r:
                item[k] = r.get(k)
        if includeRedacted and "connection_string_redacted" in r:
            item["connection_string_redacted"] = r.get("connection_string_redacted")
        out_rows.append(item)

    ended = _now()
    dur = max(0, int((time.time() - t0) * 1000))
    op["status"] = "succeeded"
    op["ended_at"] = ended
    op["duration_ms"] = dur
    op["result"] = {"count": len(out_rows), "total": total, "page": page, "pageSize": pageSize}
    op["updated_at"] = ended
    _save("mongo_operations.json", ops)

    return {
        "connections": out_rows,
        "page": page,
        "pageSize": pageSize,
        "total": total,
        "has_more": has_more,
    }
